449:     var a = Math.pow(Math.sin(deltaLat/2), 2) + Math.cos(lat1) * Math.cos(lat2) * Math.pow(Math.sin(deltaLon/2), 2);
450:     var c = 2 * Math.asin(Math.sqrt(a));
451:     var EARTH_RADIUS = 6371;
