uint16_t tab[];

void f(void) {
        uint16_t y;
        uint16_t *x;
        uint8_t *a, *b;
        

        x = tab;   
        
        while(*x) {     
                a = x[1];  
                b = &amp;x[2];  
                
                x = 0;     
                for(y = *x; y &gt; 0; y--) {
                        a[x] = b[x];
                        x++;
                }       
                
                x += b;   
        }       
}

