char *ct_isupport_param(void);

extern MODVAR MessageTagHandler *mtaghandlers;

ModuleHeader MOD_HEADER = {
	&quot;third/clienttagdeny&quot;,
	&quot;5.0&quot;,
	&quot;Informs clients about supported client tags&quot;,
	&quot;k4be@PIRC&quot;,
	&quot;unrealircd-5&quot;,
};

MOD_INIT(){
	return MOD_SUCCESS;
}

MOD_LOAD(){
	ISupportAdd(modinfo-&gt;handle, &quot;CLIENTTAGDENY&quot;, ct_isupport_param());

	return MOD_SUCCESS;
}

MOD_UNLOAD(){
	return MOD_SUCCESS;
}

#define BUFLEN 500

char *ct_isupport_param(void){
	static char buf[BUFLEN];
	MessageTagHandler *m;
	
	strcpy(buf, &quot;*&quot;);

	for (m = mtaghandlers; m; m = m-&gt;next) {
		if(m-&gt;name[0] == '+'){
			strncat(buf, &quot;,-&quot;, BUFLEN-1);
			strncat(buf, m-&gt;name+1, BUFLEN-1);
		}
	}
	return buf;
}
