	unsigned char przyc_wart;
	for(;;){
		wyswietl(23);
		przyc_wart = sprawdz_przyc();
		switch(przyc_wart){
			case 4: ust_km(); alg = losuj(); czas=75; return; break;
			case 1: if(tryb&lt;1)tryb++; break;
