	if(conf_fakechans &amp;&amp; !fakechanCount) {
		config_error(&quot;[%s] %s::fakechans was enabled but there aren't any configured channels (fakechannel {} block)&quot;, MOD_HEADER(m_listrestrict).name, MYCONF);
		errors++;
	}
